/** 기종 스펙 — 인증 데이터 기반이라 필드가 비어 있는 기종도 있다(빈 항목은 생략) */
export interface BikeSpec {
  /** 배기량(cc) */
  cc?: number;
  /** 유형 — 스쿠터·네이키드 등 (moto-kr category 원문) */
  category?: string;
  /** 권장 유종 — premium 이면 고급휘발유 */
  fuelGrade?: 'regular' | 'premium';
  /** 연료탱크 용량(L) */
  tankL?: number;
  /** 시트고(mm) */
  seatMm?: number;
  /** 중량(kg) */
  weightKg?: number;
  /** 최고출력(PS) */
  powerPs?: number;
  electric?: boolean;
}

